import { bench, describe } from 'vitest';
import { V2, makeV1, useBox, makeReactive, makePlain } from './models';

const N = 1000; // instances created per op

describe(`create ${N} instances (no access)`, () => {
  bench('ivue v2  · new Class()', () => {
    for (let i = 0; i < N; i++) new V2();
  });

  bench('native   · plain new (baseline)', () => {
    for (let i = 0; i < N; i++) makePlain();
  });

  bench('native   · reactive(new X())', () => {
    for (let i = 0; i < N; i++) makeReactive();
  });

  bench('native   · composable factory', () => {
    for (let i = 0; i < N; i++) useBox();
  });

  bench('ivue v1  · ivue(Class)', () => {
    for (let i = 0; i < N; i++) makeV1();
  });
});

import { bench, describe } from 'vitest';
import { V2, makeV1, useBox, makeReactive } from './models';

const N = 1000; // construct + read one computed, per op

describe(`construct + first .area read (${N})`, () => {
  bench('ivue v2  · new + area.value', () => {
    let s = 0;
    for (let i = 0; i < N; i++) { const o: any = new V2(); s += o.area.value; }
    if (s < 0) throw 0;
  });

  bench('native   · reactive + area', () => {
    let s = 0;
    for (let i = 0; i < N; i++) { const o: any = makeReactive(); s += o.area; }
    if (s < 0) throw 0;
  });

  bench('native   · composable + area.value', () => {
    let s = 0;
    for (let i = 0; i < N; i++) { const o = useBox(); s += o.area.value; }
    if (s < 0) throw 0;
  });

  bench('ivue v1  · ivue + area', () => {
    let s = 0;
    for (let i = 0; i < N; i++) { const o: any = makeV1(); s += o.area; }
    if (s < 0) throw 0;
  });
});

import { bench, describe } from 'vitest';
import { V2, useBox, makePlain } from './models';

const N = 10000; // method calls per op (reads reactive state each call)

// One instance each; the loop hammers a method that reads state.
const v2 = new V2() as any;
const box = useBox();
const plain = makePlain() as any;

describe(`${N} method calls that read state`, () => {
  bench('native   · composable fn (direct ref read)', () => {
    let s = 0;
    for (let i = 0; i < N; i++) s += box.w.value * box.h.value;
    if (s < 0) throw 0;
  });

  bench('native   · plain method (baseline)', () => {
    let s = 0;
    for (let i = 0; i < N; i++) s += plain.w * plain.h;
    if (s < 0) throw 0;
  });

  bench('ivue v2  · this.x.value (getter indirection)', () => {
    let s = 0;
    for (let i = 0; i < N; i++) s += v2.w.value * v2.h.value;
    if (s < 0) throw 0;
  });

  bench('ivue v2  · hoisted (const w = this.w)', () => {
    let s = 0;
    const w = v2.w, h = v2.h; // hoist the getter once — now direct ref reads
    for (let i = 0; i < N; i++) s += w.value * h.value;
    if (s < 0) throw 0;
  });
});

import { bench, describe } from 'vitest';
import { Deep } from './models';

const N = 1000;

describe(`deep 4-level hierarchy (${N})`, () => {
  bench('create only', () => {
    for (let i = 0; i < N; i++) new Deep();
  });

  bench('create + resolve super chain (tag.value)', () => {
    let s = 0;
    for (let i = 0; i < N; i++) { const o: any = new Deep(); s += o.tag.value.length; }
    if (s < 0) throw 0;
  });

  bench('create + child computed over ancestor refs (sum.value)', () => {
    let s = 0;
    for (let i = 0; i < N; i++) { const o: any = new Deep(); s += o.sum.value; }
    if (s < 0) throw 0;
  });
});

