import { describe, expect, it } from 'vitest';
import { flushPromises, mount } from '@vue/test-utils';
import IvueHero from '../../docs_v2/.vitepress/theme/components/IvueHero.vue';

describe('IvueHero live demo', () => {
  it('counter runs on the real engine: inc, double, $watch, teardown', async () => {
    const w = mount(IvueHero);
    expect(w.text()).toContain('One kilobyte.');
    expect(w.text()).toContain('waiting for the first change');

    const plus = w.findAll('button').find((b) => b.text().includes('+1'))!;
    await plus.trigger('click');
    await plus.trigger('click');
    await flushPromises();

    const vals = w.findAll('.val .n').map((n) => n.text());
