56	      const text = this.raw.value;
57	      if (!isFormulaText(text)) return evalLiteral(text);
58	      // The reads inside sheet.evaluate() (onCell/onRange → other cells'
59	      // value.value) are tracked by THIS computed's effect → auto deps.
60	      return this.sheet.evaluate(this, stripFormula(text));
61	    });
62	  }
63	
64	  // DERIVED — plain getters. Reactive via leaf tracking; zero per-instance cost.
65	  get isFormula() {
66	    return isFormulaText(this.raw.value);
67	  }
68	  get display() {
69	    return displayOf(this.value.value);
70	  }
71	  get cssClass() {
72	    return cssOf(this.value.value, this.isFormula);
73	  }
74	
75	  // Read every derived value once — used only by the measurement harness to
76	  // force full materialization of all 100k cells for the worst-case number.
77	  touch() {
78	    void this.value.value;
79	    void this.display;
80	    void this.isFormula;
81	    void this.cssClass;
