1	/**
2	 * The Sheet — a PLAIN (non-reactive) container that owns the 100,000
3	 * `FormulaCell` instances and the ONE shared formula parser.
4	 *
5	 * The reactivity lives on the cells (each has its own ref + computed); the
6	 * Sheet is just the structure + the integration seam:
7	 *
8	 *   - `grid[r0][c0]` holds the cells, giving an O(1) 1-based `cellAt(row,col)`.
9	 *   - a SINGLE `FormulaParser` (not one per cell — that would reintroduce the
10	 *     per-instance allocation this whole design fights) whose `onCell`/`onRange`
11	 *     hooks read cells' `value.value`. Because those reads happen while a cell's
12	 *     `value` computed is evaluating, VUE tracks them as real dependencies —
13	 *     the dependency graph is discovered, never hand-built.
14	 */
15	import FormulaParser from 'fast-formula-parser';
16	import { FormulaCell } from './FormulaCell';
17	import {
18	  COLS,
19	  type CellValue,
20	  initialFormula,
21	  stripFormula,
22	} from './formula-logic';
23	
24	const { FormulaError } = FormulaParser as unknown as {
25	  FormulaError: new (error: string, details?: unknown) => CellValue;
26	};
27	
28	interface RangeRef {
29	  from: { row: number; col: number };
30	  to: { row: number; col: number };
31	}
32	
33	export class Sheet {
34	  readonly rows: number;
35	  readonly cols: number;
36	  /** [row0][col0] — the cells, doubling as the O(1) cellAt index. */
37	  readonly grid: FormulaCell.Instance[][];
38	
39	  /** ONE parser for the entire sheet, shared by all cells. */
40	  private readonly parser: FormulaParser;
41	  /** Recursion guard: a cell re-entered mid-evaluation is a cycle → #REF!. */
42	  private readonly evaluating = new Set<object>();
43	  /** When non-null, cellValueAt records every (row,col) read (dep tracing). */
44	  private tracer: Array<[number, number]> | null = null;
45	
46	  constructor(rows: number, cols: number = COLS) {
47	    this.rows = rows;
48	    this.cols = cols;
49	
50	    const grid: FormulaCell.Instance[][] = new Array(rows);
51	    for (let r = 0; r < rows; r++) {
52	      const rowArr: FormulaCell.Instance[] = new Array(cols);
53	      for (let c = 0; c < cols; c++) {
54	        rowArr[c] = new FormulaCell.Class(
55	          this,
56	          r + 1,
57	          c + 1,
58	          initialFormula(r, c),
59	        );
60	      }
61	      grid[r] = rowArr;
62	    }
63	    this.grid = grid;
64	
65	    this.parser = new FormulaParser({
66	      onCell: (ref) => this.cellValueAt(ref.row, ref.col),
67	      onRange: (ref) => this.rangeValues(ref as RangeRef),
68	    });
69	  }
70	
71	  /** O(1) 1-based lookup. Out of bounds → undefined. */
72	  cellAt(row: number, col: number): FormulaCell.Instance | undefined {
73	    if (row < 1 || row > this.rows || col < 1 || col > this.cols)
74	      return undefined;
75	    return this.grid[row - 1][col - 1];
76	  }
77	
78	  /**
79	   * onCell seam — read the referenced cell's REACTIVE value. The read is
80	   * tracked by whatever computed is currently evaluating, so editing that cell
81	   * later invalidates the dependent formula automatically.
82	   */
83	  private cellValueAt(row: number, col: number): CellValue {
84	    if (this.tracer) this.tracer.push([row, col]);
85	    const cell = this.cellAt(row, col);
86	    return cell ? cell.value.value : null; // out of bounds / blank → 0 in math
87	  }
88	
89	  /** onRange seam — a 2D array of the referenced cells' values. */
90	  private rangeValues(ref: RangeRef): CellValue[][] {
91	    const { from, to } = ref;
92	    const out: CellValue[][] = [];
93	    for (let r = from.row; r <= to.row; r++) {
94	      const rowArr: CellValue[] = [];
95	      for (let c = from.col; c <= to.col; c++)
96	        rowArr.push(this.cellValueAt(r, c));
97	      out.push(rowArr);
98	    }
99	    return out;
100	  }
101	
102	  /**
103	   * Parse + evaluate a formula body (no leading '='), through the SHARED parser.
104	   * Called from a cell's `value` computed, so every onCell/onRange read inside
105	   * becomes a tracked dependency of that computed. Guarded against cycles.
106	   */
107	  evaluate(cell: { row: number; col: number }, body: string): CellValue {
108	    if (body.trim().length === 0) return null; // "=" alone → blank
109	    if (this.evaluating.has(cell)) return new FormulaError('#REF!'); // circular ref
110	    this.evaluating.add(cell);
111	    try {
112	      return this.parser.parse(body, {
113	        row: cell.row,
114	        col: cell.col,
115	        sheet: 'Sheet1',
116	      }) as CellValue;
117	    } catch (e) {
118	      return e instanceof (FormulaError as unknown as Function)
119	        ? (e as CellValue)
120	        : new FormulaError('#ERROR!');
121	    } finally {
122	      this.evaluating.delete(cell);
123	    }
124	  }
125	
126	  /**
127	   * Diagnostic: which cells does (row,col)'s formula CURRENTLY read? Re-parses
128	   * once outside Vue tracking with the read-tap on. It walks the exact same
129	   * onCell/onRange path Vue tracks, so the returned set IS the live Vue
130	   * dependency set for that cell — which is why it visibly SHIFTS when an
131	   * IF()'s condition crosses a branch boundary.
132	   */
133	  traceDeps(row: number, col: number): Array<[number, number]> {
134	    const cell = this.cellAt(row, col);
135	    if (!cell || !cell.isFormula) return [];
136	    const body = stripFormula(cell.raw.value);
137	    if (body.trim().length === 0) return [];
138	
139	    const prev = this.tracer;
140	    this.tracer = [];
141	    try {
142	      this.parser.parse(body, { row, col, sheet: 'Sheet1' });
143	    } catch {
144	      /* keep whatever reads it made before erroring */
145	    }
146	    const recorded = this.tracer;
147	    this.tracer = prev;
148	
149	    const seen = new Set<string>();
150	    const deps: Array<[number, number]> = [];
151	    for (const [r, c] of recorded) {
152	      const k = r + ',' + c;
153	      if (!seen.has(k)) {
154	        seen.add(k);
155	        deps.push([r, c]);
156	      }
157	    }
158	    return deps;
159	  }
160	
161	  /** Iterate every cell — the measurement harness uses this to force full
162	   *  materialization of all cells for the worst-case heap figure. */
163	  forEach(fn: (cell: FormulaCell.Instance) => void) {
164	    for (let r = 0; r < this.rows; r++) {
165	      const rowArr = this.grid[r];
166	      for (let c = 0; c < this.cols; c++) fn(rowArr[c]);
167	    }
168	  }
169	}
