1	/**
2	 * Page controller for the formula grid. Mirrors the plain grid demo's
3	 * `useGridPage`, adapted for the `Sheet` model:
4	 *
5	 *   - the Sheet is held in a `shallowRef` so neither it, its `grid`, nor its
6	 *     100k cells are ever deep-proxied (that would corrupt the heap comparison);
7	 *     per-cell reactivity comes entirely from each cell's own ref/computed.
8	 *   - identical row-windowing (`useRowWindow`), click-to-edit, and a
9	 *     `window.__grid` harness the Playwright measurement script drives —
10	 *     extended with `deps()` so the conditional-dependency shift can be proven.
11	 */
12	import { computed, onMounted, ref, shallowRef } from 'vue';
13	import { Sheet } from './Sheet';
14	import {
15	  COLS,
16	  OVERSCAN,
17	  ROWS,
18	  ROW_HEIGHT,
19	  VIEWPORT_HEIGHT,
20	  colLabel,
21	} from './formula-logic';
22	import { useRowWindow } from '../grid/useRowWindow';
23	
24	/** A1-style label for a 1-based (row,col). */
25	function a1(row: number, col: number): string {
26	  return colLabel(col - 1) + row;
27	}
28	
29	export function useFormulaGrid() {
30	  const sheet = shallowRef<Sheet | null>(null);
31	  const hasModel = ref(false);
32	  const creationMs = ref(0);
33	
34	  const scrollEl = ref<HTMLElement | null>(null);
35	
36	  const win = useRowWindow({
37	    rowCount: () => (sheet.value ? sheet.value.rows : 0),
38	    rowHeight: ROW_HEIGHT,
39	    viewportHeight: VIEWPORT_HEIGHT,
40	    overscan: OVERSCAN,
41	  });
42	
43	  const mountedCells = computed(() => win.visibleRows.value.length * COLS);
44	  const modelCells = computed(() =>
45	    sheet.value ? sheet.value.rows * COLS : 0,
46	  );
47	
48	  /** Build the whole sheet up front and time ONLY the instance creation. */
49	  function createModel(rowCount: number = ROWS) {
50	    editing.value = null;
51	    const t0 = performance.now();
52	    const s = new Sheet(rowCount, COLS);
53	    const t1 = performance.now();
54	    creationMs.value = t1 - t0;
55	    sheet.value = s;
56	    hasModel.value = true;
57	    // eslint-disable-next-line no-console
58	    console.log(
59	      `[formula] created ${rowCount * COLS} cells in ${creationMs.value.toFixed(2)}ms`,
60	    );
61	  }
62	
63	  // --- click-to-edit ---
64	  const editing = ref<{ r: number; c: number } | null>(null);
65	  const isEditing = (r: number, c: number) =>
66	    !!editing.value && editing.value.r === r && editing.value.c === c;
67	  const edit = (r: number, c: number) => {
68	    editing.value = { r, c };
69	  };
70	  const commitEdit = () => {
71	    editing.value = null;
72	  };
73	
74	  // --- programmatic drivers used by the measurement harness (0-based r,c) ---
75	  function setScroll(px: number) {
76	    const max = Math.max(0, win.totalHeight.value - VIEWPORT_HEIGHT);
77	    const clamped = Math.min(Math.max(0, px), max);
78	    win.scrollTop.value = clamped;
79	    if (scrollEl.value) scrollEl.value.scrollTop = clamped;
80	  }
81	  function editCell(r: number, c: number, v: string) {
82	    const cell = sheet.value?.cellAt(r + 1, c + 1);
83	    if (cell) cell.raw.value = v;
84	  }
85	  function materializeAll() {
86	    const s = sheet.value;
87	    if (!s) return;
88	    const t0 = performance.now();
89	    s.forEach((cell) => cell.touch());
90	    // eslint-disable-next-line no-console
91	    console.log(
92	      `[formula] materialized all cells in ${(performance.now() - t0).toFixed(2)}ms`,
93	    );
94	  }
95	
96	  onMounted(() => {
97	    (window as any).__grid = {
98	      arm: 'formula',
99	      cols: COLS,
100	      createModel: (rowCount?: number) => createModel(rowCount),
101	      hasModel: () => hasModel.value,
102	      creationMs: () => creationMs.value,
103	      mountedCount: () => document.querySelectorAll('[data-grid-cell]').length,
104	      scrollToRow: (r: number) =>
105	        setScroll(r * ROW_HEIGHT - VIEWPORT_HEIGHT / 2),
106	      setScroll,
107	      editCell,
108	      materializeAll,
109	      cellText: (r: number, c: number) => {
110	        const el = document.querySelector(
111	          `[data-grid-cell][data-row="${r}"][data-col="${c}"]`,
112	        );
113	        return el ? (el.textContent || '').trim() : null;
114	      },
115	      /** The literal formula/text the cell holds. */
116	      cellRaw: (r: number, c: number) =>
117	        sheet.value?.cellAt(r + 1, c + 1)?.raw.value ?? null,
118	      /** The cell's resolved value (number/string/error), for assertions. */
119	      cellValue: (r: number, c: number) => {
120	        const v = sheet.value?.cellAt(r + 1, c + 1)?.value.value;
121	        return v && typeof v === 'object' ? String(v) : (v ?? null);
122	      },
123	      /** The live tracked dependency set of a formula cell, as A1 refs. */
124	      deps: (r: number, c: number) =>
125	        (sheet.value?.traceDeps(r + 1, c + 1) ?? []).map(([rr, cc]) => ({
126	          row: rr,
127	          col: cc,
128	          ref: a1(rr, cc),
129	        })),
130	    };
131	  });
132	
133	  return {
134	    // config
135	    COLS,
136	    colLabel,
137	    // state
138	    sheet,
139	    hasModel,
140	    creationMs,
141	    mountedCells,
142	    modelCells,
143	    // windowing
144	    scrollEl,
145	    totalHeight: win.totalHeight,
146	    offsetY: win.offsetY,
147	    visibleRows: win.visibleRows,
148	    onScroll: win.onScroll,
149	    // interaction
150	    editing,
151	    isEditing,
152	    edit,
153	    commitEdit,
154	    createModel,
155	  };
156	}
