1	/**
2	 * Shared, arm-agnostic configuration + PURE cell logic for the formula grid.
3	 *
4	 * Nothing here is reactive and nothing here imports the parser — these are the
5	 * plain functions the reactive `FormulaCell` wraps. Keeping them pure means the
6	 * cell class stays a thin reactivity shell (one `computed()` + plain getters)
7	 * and the same functions can be unit-reasoned about in isolation.
8	 */
9	
10	/** Grid shape — 40 columns × 2,500 rows = 100,000 cells. */
11	export const COLS = 40;
12	export const ROWS = 2500;
13	export const CELL_COUNT = COLS * ROWS; // 100,000
14	
15	/** The scaled-up option — 40 columns × 25,000 rows = 1,000,000 cells. */
16	export const ROWS_1M = 25000;
17	
18	/** Row-windowing geometry (identical to the plain grid demo). */
19	export const ROW_HEIGHT = 28; // px
20	export const VIEWPORT_HEIGHT = 448; // px  → ~16 rows on screen
21	export const OVERSCAN = 4; // extra rows above/below the viewport
22	
23	/**
24	 * The running-sum column resets every RUNSUM_BLOCK rows so no dependency chain
25	 * is thousands of levels deep (a cold read of the bottom of a full-height chain
26	 * would recurse through the parser thousands of times). A block of 50 keeps the
27	 * chain shallow while still cascading across ~3 screens when the top is edited.
28	 */
29	export const RUNSUM_BLOCK = 50;
30	
31	/** A value a cell can resolve to. `FormulaError` is detected structurally. */
32	export type CellValue =
33	  number | string | boolean | null | { _error?: string; error?: string };
34	
35	/** Spreadsheet-style column label: 0→A, 25→Z, 26→AA … */
36	export function colLabel(n: number): string {
37	  let s = '';
38	  let x = n + 1;
39	  while (x > 0) {
40	    const m = (x - 1) % 26;
41	    s = String.fromCharCode(65 + m) + s;
42	    x = Math.floor((x - 1) / 26);
43	  }
44	  return s;
45	}
46	
47	/**
48	 * Deterministic numeric input for a data cell: a repeatable mix of
49	 * positives/negatives/decimals with ~8% blanks (so `cssClass` and the blank
50	 * dot vary). Kept purely numeric so the formulas that reference these columns
51	 * never error on the initial data — text can still be typed in live.
52	 * Same (row,col) → same value on every build.
53	 */
54	export function numData(row: number, col: number): string {
55	  const seed = row * COLS + col;
56	  if (seed % 13 === 5) return ''; // ~7.7% blanks
57	  const v = ((seed * 2654435761) % 100000) / 100 - 500; // −500 … 500
58	  return (Math.round(v * 100) / 100).toString();
59	}
60	
61	/**
62	 * The literal text every cell starts with — REAL Excel-formula syntax wired so
63	 * roughly half the grid is cross-referencing formulas and the other half is the
64	 * numeric source data they read. `row`/`col` are 0-based here; the A1 refs they
65	 * emit are 1-based.
66	 *
67	 * Column map (per row r = row + 1):
68	 *   A B C D (0-3) input numbers            — the source data
69	 *   E   (4)  =A+B                          — cross-cell arithmetic
70	 *   F   (5)  =C-D                           — cross-cell arithmetic
71	 *   G   (6)  =SUM(A:D)                      — range, exercises onRange
72	 *   H   (7)  =AVERAGE(A:D)                  — range, exercises onRange
73	 *   I   (8)  =IF(A>0, B, C)                 — CONDITIONAL dependency (marquee)
74	 *   J   (9)  =J(r-1)+A  (block-reset)       — running sum (marquee cascade)
75	 *   K…AN(10+) even col = input, odd col = =<left1>+<left2>  (cross-column mesh)
76	 */
77	export function initialFormula(row: number, col: number): string {
78	  const r = row + 1; // 1-based row for A1 notation
79	  switch (col) {
80	    case 0:
81	    case 1:
82	    case 2:
83	    case 3:
84	      return numData(row, col);
85	    case 4:
86	      return `=A${r}+B${r}`;
87	    case 5:
88	      return `=C${r}-D${r}`;
89	    case 6:
90	      return `=SUM(A${r}:D${r})`;
91	    case 7:
92	      return `=AVERAGE(A${r}:D${r})`;
93	    case 8:
94	      return `=IF(A${r}>0,B${r},C${r})`;
95	    case 9:
96	      // Running sum, reset at the top of each RUNSUM_BLOCK-row block.
97	      return row % RUNSUM_BLOCK === 0 ? `=A${r}` : `=J${r - 1}+A${r}`;
98	    default:
99	      // Filler mesh: even columns are input data; odd columns sum the two
100	      // cells immediately to their left (one data, one formula) — a real
101	      // cross-column dependency, not a decorative one.
102	      if (col % 2 === 0) return numData(row, col);
103	      return `=${colLabel(col - 1)}${r}+${colLabel(col - 2)}${r}`;
104	  }
105	}
106	
107	/** Does the literal text start (after leading spaces) with '='? */
108	export function isFormulaText(text: string): boolean {
109	  const t = text.trimStart();
110	  return t.length > 0 && t[0] === '=';
111	}
112	
113	/** Strip the leading '=' (and any leading spaces) to get the formula body. */
114	export function stripFormula(text: string): string {
115	  return text.trimStart().slice(1);
116	}
117	
118	/** Structural FormulaError detection — avoids importing the parser here. */
119	export function isFormulaError(
120	  value: CellValue,
121	): value is { _error?: string; error?: string } {
122	  return (
123	    typeof value === 'object' &&
124	    value !== null &&
125	    ('_error' in value || 'error' in value)
126	  );
127	}
128	
129	/**
130	 * Resolve a NON-formula literal to its value: '' → null (blank, SUMs as 0),
131	 * a numeric string → a number, anything else → the text verbatim.
132	 */
133	export function evalLiteral(text: string): CellValue {
134	  const t = text.trim();
135	  if (t.length === 0) return null;
136	  const n = Number(t);
137	  return !Number.isNaN(n) && Number.isFinite(n) ? n : text;
138	}
139	
140	/** Display string for a resolved value. */
141	export function displayOf(value: CellValue): string {
142	  if (value == null) return '·';
143	  if (isFormulaError(value))
144	    return String(value.error ?? value._error ?? '#ERR');
145	  if (typeof value === 'number') {
146	    return Number.isFinite(value)
147	      ? value.toLocaleString('en-US', { maximumFractionDigits: 2 })
148	      : String(value);
149	  }
150	  if (typeof value === 'boolean') return value ? 'TRUE' : 'FALSE';
151	  return String(value);
152	}
153	
154	/** CSS class driven by error-ness, number sign, and whether it's a formula. */
155	export function cssOf(value: CellValue, isFormula: boolean): string {
156	  let base: string;
157	  if (isFormulaError(value)) base = 'gc-err';
158	  else if (value == null) base = 'gc-zero';
159	  else if (typeof value === 'number')
160	    base = value < 0 ? 'gc-neg' : value > 0 ? 'gc-pos' : 'gc-zero';
161	  else base = 'gc-text';
162	  return isFormula ? base + ' gc-formula' : base;
163	}
