import { describe, expect, it } from 'vitest';
import { flushPromises, mount } from '@vue/test-utils';
import FormulaGrid from '../../docs_v2/.vitepress/theme/components/grid/FormulaGrid.vue';

const cellDiv = (w: any, r: number, c: number) =>
  w.find(`[data-grid-cell][data-row="${r}"][data-col="${c}"]`);

describe('FormulaGrid docs embed', () => {
  it('create → evaluate → DOM cascade → conditional-dep shift', async () => {
    const w = mount(FormulaGrid);
    expect(w.text()).toContain('Nothing built yet');

    // create 100k (parser arrives via dynamic import — poll)
    await w
      .findAll('button')
      .find((b) => b.text().includes('Create 100k'))!
      .trigger('click');
    for (let i = 0; i < 60 && !w.text().includes('100,000 cells'); i++) {
      await new Promise((r) => setTimeout(r, 100));
      await flushPromises();
    }
    expect(w.text()).toContain('100,000 cells');

    // real evaluation in the DOM: E1 = A1+B1 = -500 + -142.39
    expect(cellDiv(w, 0, 4).text()).toContain('642.39');

    // conditional deps while A1 < 0: I1 reads {A1, C1}
    await cellDiv(w, 0, 8).trigger('click');
    await flushPromises();
    expect(w.text()).toContain('reads: A1, C1');

    // edit A1 → 5000 via the UI
    await cellDiv(w, 0, 0).trigger('click');
    const input = w.find('input.gc-edit');
    await input.setValue('5000');
    await input.trigger('blur');
    await flushPromises();

    // cascade hit the rendered DOM: E1 = 5000 - 142.39
    expect(cellDiv(w, 0, 4).text()).toContain('4,857.61');

    // the tracked dependency set SHIFTED branches: now {A1, B1}
    await cellDiv(w, 0, 8).trigger('click');
    await flushPromises();
    expect(w.text()).toContain('reads: A1, B1');

    w.unmount();
  }, 60000);
});
EOF
